670	    let kv_dim = model.local_kv_dim();
671	    let intermediate = model.local_intermediate_size();
672	    // Unified-N peak: one prefill chunk (≤ max_prefill_tokens) + (max_bucket−1) concurrent decoders;
673	    // rests on max_decode_batch_size == BATCH_BUCKETS.last().
674	    let ceiling = max_prefill_tokens + (*BATCH_BUCKETS.last().unwrap()).saturating_sub(1);
675	    // lm_head (logits_rows×hidden) runs on the sampled-position count, not the token count: decode-only
676	    // pads to a bucket (≤ max_decode_batch_size) and unified gathers ≤ that many requests, while
677	    // all-position scoring runs up to max_prefill_tokens — true max N = max(max_prefill, max_decode_batch).
678	    let lm_head_max_n = max_prefill_tokens.max(*BATCH_BUCKETS.last().unwrap());
679	    let shapes = crate::batch_decode_buffers::decode_projection_pin_shapes(
680	        hidden,
681	        q_dim,
682	        kv_dim,
683	        intermediate,
684	        model.config().logits_rows,
685	    );
