687	    // every projection, the sampled-position count for lm_head.
688	    let max_ns = [ceiling, ceiling, ceiling, ceiling, ceiling, lm_head_max_n];
689	    let mut checks = 0usize;
690	    for (&(m, k), &max_n) in shapes.iter().zip(max_ns.iter()) {
691	        for n in 1..=max_n {
