734	/// Process-global numeric policy for projection GEMMs (atomics, not thread-local: set on the main
735	/// thread before worker construction, read on the worker). `Tuned` (default) = production path;
736	/// `Pin` = batch-invariant pinned algo (one cuBLASLt algo per `(M,K)`; `launch_gemm_pin` bails — no
737	/// per-token fallback — if it can't serve an N or under a stream override); `PerToken` = N=1 oracle.
738	/// Set via `set_numeric_policy` before executor
739	/// construction / graph capture.
740	#[derive(Clone, Copy, PartialEq, Eq, Debug)]
741	#[repr(u8)]
742	pub enum NumericPolicy {
743	    Tuned = 0,
744	    Pin = 1,
745	    PerToken = 2,
746	}
747	
748	static NUMERIC_POLICY: AtomicU8 = AtomicU8::new(NumericPolicy::Tuned as u8);
749	static PIN_SERVED: AtomicU64 = AtomicU64::new(0);
750	static PER_TOKEN_SERVED: AtomicU64 = AtomicU64::new(0);
751	
752	/// Set the process-global policy. Must run before executor construction / graph capture (the
753	/// captured algo is the one live at capture). Tests drive baseline/pin/per-token through it.
754	pub fn set_numeric_policy(p: NumericPolicy) {
755	    NUMERIC_POLICY.store(p as u8, Ordering::Release);
756	}
757	
758	pub fn numeric_policy() -> NumericPolicy {
759	    match NUMERIC_POLICY.load(Ordering::Acquire) {
760	        1 => NumericPolicy::Pin,
761	        2 => NumericPolicy::PerToken,
762	        _ => NumericPolicy::Tuned,
763	    }
764	}
765	
766	/// NUMERIC_POLICY defaults to Tuned; only qwen3 sets Pin/PerToken, so typed GEMM (kimi) never fires this.
767	pub(crate) fn ensure_tuned_policy(m: usize, n: usize, k: usize) -> Result<()> {
768	    let policy = numeric_policy();
769	    ensure!(
770	        policy == NumericPolicy::Tuned,
771	        "typed GEMM is not covered by the batch-invariant pin: policy={policy:?}, m={m}, n={n}, k={k}"
772	    );
773	    Ok(())
774	}
