1	//! End-to-end prefill repro: pinning the projection GEMMs makes prompt_a's next-token top-K stop
2	//! depending on its batch-mates in this tested prefill path. Scope is the GEMM-N reduction-order
3	//! axis of the prefill API — the decode axes belong to `batch_invariance_attention_path`
4	//! (attention-path) and `batch_invariance_unified` (decode-vs-unified).
5	//!
6	//! prompt_a's top-K alone vs co-batched with a filler, under three policies: baseline (Tuned,
7	//! drifts = the bug), pin (top-K bit-identical = the fix), per_token (oracle). Pass requires full
8	//! ordered top-K equality + a baseline-drift guard + served>0 (per-token fallback under Pin is
9	//! impossible — `launch_gemm_pin` bails, surfacing as a prefill `.expect` panic).
10	//!
11	//!   PEGAINFER_TEST_MODEL_PATH=<Qwen3-4B-base> cargo test --release \
12	//!     -p pegainfer-qwen3 --test batch_invariance_endtoend -- --nocapture
13	
14	use pegainfer_frontend::sampler::SamplingParams;
15	use pegainfer_kernels::ops::NumericPolicy;
16	use pegainfer_kernels::ops::pin_served;
17	use pegainfer_kernels::ops::reset_numeric_policy_counters;
18	use pegainfer_kernels::ops::set_numeric_policy;
19	use pegainfer_qwen3::runtime::PrefillPlan;
20	use pegainfer_qwen3::runtime::PrefillStepItem;
21	use pegainfer_qwen3::runtime::Qwen3Executor;
22	use pegainfer_qwen3::runtime::RequestId;
23	
24	const LOGPROBS: usize = 64;
25	const MAX_OUTPUT_TOKENS: usize = 4;
