/// Resets the pin and per-token served counters.
pub fn reset_numeric_policy_counters() {
    PIN_SERVED.store(0, Ordering::Relaxed);
    PER_TOKEN_SERVED.store(0, Ordering::Relaxed);
}

/// Fixed representative N at which every (M,K) pin is resolved — one algo for ALL
/// N (NOT first-call-N, which would make the pinned algo call-order-dependent).
const PIN_REP_N: i32 = 32;

/// Pin one `(num_rows, cols)` algo at the canonical `PIN_REP_N`, reused for all N.
pub fn gemm_lt_pin_warmup(num_rows: usize, cols: usize) -> Result<PinAlgoConfig> {
    gemm_lt_pin_tune(num_rows, PIN_REP_N as usize, cols)
}

/// `Pin` policy: run the boot-warmed pinned (m,k) algo at live N; bails if (m,k) isn't pinned or the
/// algo can't serve N (no lazy tune, no per-token fallback, which would break invariance).
fn launch_gemm_pin(
    w_ptr: *const ffi::Half,
    x_ptr: *const ffi::Half,
    y_ptr: *mut ffi::Half,
    m: usize,
    n: usize,
    k: usize,
    ctx: &DeviceContext,
) -> Result<()> {
    // decode-overlap (the only stream-override source) is rejected before capture, so a stream
    // override here is misuse — bail rather than fall back to per-token.
    if crate::tensor::has_stream_override() {
        bail!(
            "batch-invariant Pin GEMM cannot run under a stream override (m={m}, n={n}, k={k}): \
             --batch-invariant is incompatible with --decode-overlap; run without one of them"
        );
    }
    // Only the boot-warmed base projections are pinned; any other (m,k) is unverified —
    // gemm_lt_pin_cuda returns GEMM_LT_PIN_UNTUNED and the match below bails. No lazy tune: it would
    // run an unchecked shape and allocate illegally mid-capture.
    unsafe {
        let status = ffi::gemm_lt_pin_cuda(
            w_ptr,
            x_ptr,
            y_ptr,
            m as i32,
            n as i32,
            k as i32,
            crate::tensor::active_cu_stream(ctx),
        );
        match status {
            0 => {
                PIN_SERVED.fetch_add(1, Ordering::Relaxed);
                Ok(())
            }
            GEMM_LT_PIN_UNSUPPORTED | GEMM_LT_PIN_UNTUNED => bail!(
                "batch-invariant Pin GEMM cannot serve N={n} at (m={m}, k={k}): either this N is \
                 outside the pinned envelope, or (M,K) was never warmed (e.g. a DFlash drafter or \
                 LoRA prefill-delta shape), or the numeric policy was set after executor \
                 construction. Run without --batch-invariant or report this shape"
            ),
            s => bail!(
                "pin GEMM failed: {}, m={m}, n={n}, k={k}",
                ffi_status_detail(s)
            ),
        }
    }
}

/// `PerToken` policy: the N=1-per-column oracle (invariant by construction).
fn launch_gemm_pertoken(
    w_ptr: *const ffi::Half,

/// independently resident graph executable. The diagnostic PerToken policy
/// therefore retains graphs only through bucket 32.
///
/// Buckets 8/16 are viable only because decode GEMMs at N <= GEMM_LT_MAX_N run
/// tuned cublasLt algos: cuBLAS's GemmEx heuristic skips split-K for batch in
/// [8, 16] (RTX 5090 ctx1024: 9.2/9.3ms steps vs 7.9ms at bs20), while the Lt
/// heuristic list has full-speed candidates at every small N.
pub(crate) const BATCH_BUCKETS: &[usize] = &[
    1, 2, 4, 8, 16, 20, 24, 32, 40, 48, 56, 64, 72, 80, 88, 96, 104, 112, 120, 128, 136, 144, 152,
    160, 168, 176, 184, 192, 200, 208, 216, 224, 232, 240, 248, 256,
];

const DECODE_ATTENTION_PATH_COUNT: usize = 2;
// Split-KV decode attention: the non-partitioned kernel issues one CTA per
// (request x kv-head), starving SMs at small batch. The path is therefore
// chosen by batch (CTA count vs SM count), NOT context length — at bs=1 the
// 8 CTAs underfill the GPU at any seq_len, so SplitKv wins across the whole
// context range. SPLIT_KV_MAX_BATCH_SIZE caps it where NonPartition's CTAs
// already saturate the SMs (bs<=8 wins big, ~bs16 even, bs32 within ~1%).
// 64-token chunks measured fastest on RTX 5090 (128/256 are 1-7% slower, 32
// past the merge-overhead knee). Measurements: docs/models/qwen3/decode-attention.md.
pub const SPLIT_KV_CHUNK_TOKENS: usize = 64;
pub const SPLIT_KV_TUNED_MAX_CHUNKS: usize = 64; // Tuned adaptive-split count cap
const SPLIT_KV_MAX_CHUNKS_PER_REQUEST: usize = 256; // split-KV workspace/guard bound
const SPLIT_KV_MAX_BATCH_SIZE: usize = 32;

/// The split-KV config for `policy`: 64-token floor + per-policy cap (Tuned 64, Pin/PerToken 256).
const fn split_kv_config(policy: NumericPolicy) -> SplitKvConfig {
    let max_chunks = match policy {
        NumericPolicy::Tuned => SPLIT_KV_TUNED_MAX_CHUNKS,
        NumericPolicy::Pin | NumericPolicy::PerToken => SPLIT_KV_MAX_CHUNKS_PER_REQUEST,
    };
    SplitKvConfig::new(SPLIT_KV_CHUNK_TOKENS, max_chunks)
}

